```js
import crypto from 'node:crypto';
import events from './events.json' with {type:'json'};

const CURSOR_SECRET = 'events-list-cursor-v1';

export async function listTools() {
  return [
    {
      name: 'events_list',
      description: 'List events in source order with cursor-based pagination.',
      inputSchema: {
        type: 'object',
        properties: {
          cursor: {
            type: 'string',
            description: 'Opaque pagination cursor returned by a previous events_list call. Omit for the first page.'
          },
          page_size: {
            type: 'integer',
            minimum: 1,
            maximum: 3,
            description: 'Number of events to return per page. Must be between 1 and 3. Defaults to 2.'
          }
        },
        additionalProperties: false
      }
    }
  ];
}

function sign(payload) {
  return crypto.createHmac('sha256', CURSOR_SECRET).update(payload).digest('hex').slice(0, 16);
}

function makeCursor(index) {
  const payload = Buffer.from(JSON.stringify({ i: index }), 'utf8').toString('base64url');
  return payload + '.' + sign(payload);
}

function parseCursor(cursor) {
  if (typeof cursor !== 'string' || cursor.length === 0) {
    throw new Error('Invalid cursor');
  }
  const dot = cursor.lastIndexOf('.');
  if (dot <= 0 || dot === cursor.length - 1) {
    throw new Error('Invalid cursor');
  }
  const payload = cursor.slice(0, dot);
  const sig = cursor.slice(dot + 1);
  if (sign(payload) !== sig) {
    throw new Error('Unknown cursor');
  }
  let parsed;
  try {
    parsed = JSON.parse(Buffer.from(payload, 'base64url').toString('utf8'));
  } catch {
    throw new Error('Invalid cursor');
  }
  if (!parsed || typeof parsed !== 'object' || !Number.isInteger(parsed.i)) {
    throw new Error('Invalid cursor');
  }
  return parsed.i;
}

export async function callTool(name, args = {}) {
  if (name !== 'events_list') {
    throw new Error('Unknown tool: ' + name);
  }

  const known = new Set(['cursor', 'page_size']);
  for (const key of Object.keys(args)) {
    if (!known.has(key)) {
      throw new Error('Unknown argument: ' + key);
    }
  }

  let startIndex = 0;
  if (args.cursor !== undefined && args.cursor !== null) {
    if (typeof args.cursor !== 'string') {
      throw new Error('cursor must be a string');
    }
    startIndex = parseCursor(args.cursor);
    if (!Number.isInteger(startIndex) || startIndex < 0 || startIndex > events.length) {
      throw new Error('Unknown cursor');
    }
  }

  let pageSize = args.page_size;
  if (pageSize === undefined || pageSize === null) {
    pageSize = 2;
  } else {
    if (typeof pageSize !== 'number' || !Number.isInteger(pageSize)) {
      throw new Error('page_size must be an integer between 1 and 3');
    }
    if (pageSize < 1 || pageSize > 3) {
      throw new Error('page_size must be between 1 and 3');
    }
  }

  const page = events.slice(startIndex, startIndex + pageSize);
  const endIndex = startIndex + pageSize;
  const result = { events: page };
  if (endIndex < events.length) {
    result.next_cursor = makeCursor(endIndex);
  }
  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
}
