    name: 'events_list',
    description: 'List events in source order with optional cursor pagination.',
    inputSchema: {
      type: 'object',
      properties: {
        cursor: { type: 'string', description: 'Opaque pagination cursor returned by a previous events_list call.' },
        page_size: { type: 'integer', minimum: MIN_PAGE_SIZE, maximum: MAX_PAGE_SIZE, default: DEFAULT_PAGE_SIZE, description: 'Number of events to return per page (1-3). Defaults to 2.' }
