    pageSize = args.page_size;
  }

  const slice = events.slice(offset, offset + pageSize);
  const nextOffset = offset + pageSize;
  const next_cursor = nextOffset < events.length ? encodeCursor(nextOffset) : null;

  return {
    content: [{
      type: 'text',
      text: JSON.stringify({ events: slice, next_cursor })
