+// Opaque, stateless cursor: base64 of a small JSON payload carrying the offset.
+// Clients must not interpret it; the server validates it on the way back in.
+function encodeCursor(offset) {
+  return Buffer.from(JSON.stringify({ o: offset }), 'utf8').toString('base64');
