+
+function decodeCursor(cursor) {
+  if (typeof cursor !== 'string' || cursor.length === 0) return null;
+  let json;
+  try {
+    json = JSON.parse(Buffer.from(cursor, 'base64').toString('utf8'));
+  } catch {
+    return null;
+  }
+  if (
+    !json ||
+    typeof json !== 'object' ||
+    Array.isArray(json) ||
+    !Object.prototype.hasOwnProperty.call(json, 'o')
+  ) {
+    return null;
+  }
+  const o = json.o;
+  // Only offsets that point at a real event are "known". Past-the-end or
+  // malformed values are treated as unknown cursors.
+  if (!Number.isInteger(o) || o < 0 || o >= events.length) return null;
+  return o;
